style.css:
@-moz-document domain("youtube.com") {
/* Hide YouTube's default SVG logo */
  #logo-icon svg,
  ytd-topbar-logo-renderer svg {
    display: none !important;
  }

  /* Replace it with your custom image */
  #logo-icon,
  ytd-topbar-logo-renderer #logo {
    background-image: url("https://media.discordapp.net/attachments/1400232285579776214/1435413196243599391/download_1.png?ex=690be036&is=690a8eb6&hm=1b339b1b341a42c152e1c6d42246c52819e2d1a8ca6dd2bbba84e9ea4f38f44d&=&format=webp&quality=lossless&width=342&height=245") !important;
    background-repeat: no-repeat !important;
    background-size: contain !important;
    background-position: center !important;
    width: 120px !important;
    height: 40px !important;
  }
}
